# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs, offset=-1):
    return [v - offset for v in xs]

# region: render
def render(xs):
    return [v * v for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return fold(gather(render(digest(intake(sift(raw))))))

